import { defineConfig, mergeConfig } from 'vitest/config';
import { resolve } from 'node:path';
import viteConfig from './vite.config.ts';

// Vitest config that extends the main Vite/SvelteKit config and aliases the
// SvelteKit $env/static/public module to a test mock (the real module is
// generated by svelte-kit sync and is not available in the unit-test runner).
export default mergeConfig(
	viteConfig,
	defineConfig({
		resolve: {
			alias: {
				'$env/static/public': resolve(import.meta.dirname, 'src/lib/test/mocks/env-static-public.ts')
			}
		}
	})
);
